-- BS#2833 (epic BS#2828) -- `genre_artist_crossreference.code_comp_letter`, the section letter of a Rock/Soundtracks compilation shelf slot, with a shape CHECK, a slot CHECK (a letter only where `artist_genre_code = 0`) and a partial unique index on `(genre_id, code_comp_letter)`. Schema only: no reader or writer in this migration, and every existing row stays NULL until the backfill runs.
--
-- Locks, all held until the shared migrate transaction commits. The ADD COLUMN is nullable with no default, so it rewrites no rows. The two ADD CONSTRAINT ... CHECK statements validate by scanning the table, and the CREATE UNIQUE INDEX scans it too (built in-migration, not CONCURRENTLY, since a migration runs inside a transaction), all under the AccessExclusiveLock the first ALTER TABLE takes. `genre_artist_crossreference` holds one row per artist and genre, a few thousand rows, so each step finishes in well under a second.
--
-- @no-precondition-needed: the new column is NULL for every existing row, so neither CHECK (NULL passes the shape CHECK, and the slot CHECK is satisfied by `IS NULL`) nor the partial unique index (which excludes NULLs) can be violated.
ALTER TABLE "wxyc_schema"."genre_artist_crossreference" ADD COLUMN "code_comp_letter" varchar(1);--> statement-breakpoint
CREATE UNIQUE INDEX "genre_artist_crossreference_genre_comp_letter_key" ON "wxyc_schema"."genre_artist_crossreference" USING btree ("genre_id","code_comp_letter") WHERE "wxyc_schema"."genre_artist_crossreference"."code_comp_letter" IS NOT NULL;--> statement-breakpoint
ALTER TABLE "wxyc_schema"."genre_artist_crossreference" ADD CONSTRAINT "genre_artist_crossreference_code_comp_letter_shape_ck" CHECK ("wxyc_schema"."genre_artist_crossreference"."code_comp_letter" ~ '^[A-Z]$');--> statement-breakpoint
ALTER TABLE "wxyc_schema"."genre_artist_crossreference" ADD CONSTRAINT "genre_artist_crossreference_code_comp_letter_slot_ck" CHECK ("wxyc_schema"."genre_artist_crossreference"."code_comp_letter" IS NULL OR "wxyc_schema"."genre_artist_crossreference"."artist_genre_code" = 0);